import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天山遁","description":"周易折中 - 天山遁","frontmatter":{"title":"天山遁","description":"周易折中 - 天山遁"},"headers":[],"relativePath":"zh/classics/zhezhong/039.md","filePath":"zh/classics/zhezhong/039.md"}'),h={name:"zh/classics/zhezhong/039.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="天山遁" tabindex="-1">天山遁 <a class="header-anchor" href="#天山遁" aria-label="Permalink to “天山遁”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>遁序卦曰：恒者，乆也。物不可以乆居其所，故受之以遁。遁者，退也。夫乆则有去，相须之理也。遁所以继恒也。遁，退也，避也，去之之谓也。为卦天下有山，天在上之物，阳性上进；山高起之物，形虽高起，体乃止物。有上陵之象，而止不进，天乃上进而去之，下陵而上去，是相违遁，故为遁去之义。二阴生于下，阴长将盛，阳消而退，小人渐盛，君子退而避之，故为遁也。</p><p>遁：亨，小利贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>遁，退避也。为卦二阴浸长，阳当退避，故为遁，六月之卦也。阳虽当遁，然九五当位而下有六二之应，若犹可以有为。但二阴浸长于下，则其势不可以不遁，故其占为：君子能遁，则身虽退而道亨；小人则利于守正，不可以浸长之故而遂侵迫于阳也。小谓阴柔小人也。此卦之占与“否”之初二两爻相类。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>遁者，阴长阳消，君子遁藏之时也。君子退藏以伸其道，道不屈则为亨，故遁所以有亨也。在事亦有由遁避而亨者，虽小人道长之时，君子知几退避固善也。然事有不齐，与时消息，无必同也。阴柔方长而未至于甚盛，君子尚有迟迟致力之道，不可大贞而尚利小贞也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子易说 问：“遁，小利贞”。本义谓小人也。案易中“小”字，未有以为小人者，如“小利有攸往”与“小贞吉”之类，皆大小之“小”耳？ 曰：经文固无此例，以彖传推之，则是指小人而言。今当且依经而存传耳。</p></li><li><p>问：“遁，小利贞”。本义谓小人也。案易中“小”字，未有以为小人者，如“小利有攸往”与“小贞吉”之类，皆大小之“小”耳？ 曰：经文固无此例，以彖传推之，则是指小人而言。今当且依经而存传耳。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>“小利贞”之义，传义说各不同。据易例，则似传说为长。盖至于三阴之否，则直曰“不利君子贞矣”。遁犹未至于否，但当逊避以善处之，不可过甚以激成其势，故曰“小利贞”也。</p><p>象曰：天下有山，遁；君子以远小人，不恶而严</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>天体无穷，山高有限，遁之象也。严者，君子自守之常，而小人自不能近。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>天下有山，山下起而乃正，天上进而相违，是遁避之象也。君子观其象，以避远乎小人。远小人之道，若以恶声厉色，适足以致其怨忿；惟在乎矜庄威严，使知敬畏，则自然远矣。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>石氏介曰：不恶而严，外顺而内正也。尚恶则小人憎，不严则正道消。</p></li><li><p>张子曰：“恶”读为憎恶之“恶”。远小人不可示以恶，恶则患及之，又焉能远？严之为言，敬小人而远之之意也。</p></li><li><p>杨氏时曰：天下有山，其藏疾也无所拒，然亦终莫之陵也。此君子远小人不恶而严之象也。</p></li><li><p>郭氏雍曰：君子当遁之时，畏小人之害，志在远之而已。远之之道何如？不恶其人而严其分是也。孔子曰：“疾之已甚，乱也。”不恶则不疾矣。</p></li><li><p>俞氏琰曰：君子观象以远小人，岂有他哉？不过危行言逊而已。逊其言则不恶，不使之怨也；危其行则有不可犯之严，不使之不逊也。此君子远小人之道也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>天下有山，以山喻小人，以天喻君子，似未切。盖天下有山，山之高峻极于天也。山之高峻者，未尝绝人，而自不可攀跻，故有不恶而严之象。杨氏之说，盖是此意。</p><p>彖曰：遁亨，遁而亨也。刚当位而应，与时行也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以九五一爻释亨义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>小人道长之时，君子遁退，乃其道之亨也。君子遁藏，所以伸道也。此言处遁之道，自“刚当位而应”以下，则论时与卦才，尚有可为之理也。虽遁之时，君子处之，未有必遁之义。五以刚阳之德，处中正之位，又下与六二以中正相应，虽阴长之时，如卦之才，尚当随时消息，苟可以致其力，无不至诚自尽以扶持其道，未必于遁藏而不为，故曰“与时行也”。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：此释遁之所以得亨通之义。小人之道方长，君子非遁不通，故曰“遁而亨也”。又曰释所以能遁而致亨之由，良由九五以刚而当其位，有应于二，非为否亢。遁不否亢，即是相时而动，所以遁而得亨。</p></li><li><p>郭氏忠孝曰：圣人进退皆道，无入而不自得，虽遁亦亨也。与时行者，时止则止，时行则行，是为遁之义也。</p></li><li><p>朱子语类 问：“遁亨，遁而亨也，分明是说能遁便亨，更说‘刚当位而应，与时行也’是如何？”曰：“此其所以遁而亨也。阴方㣲为他，刚当位而应，所以能知时而遁，是能与时行。不然，便是与时背也。”</p></li><li><p>吴氏曰慎曰：非以刚当位而应，犹可亨，惟其当位而应，能顺时而遁，所以亨也。与时行，谓时当遁而遁。</p></li></ul><p>小利贞，浸而长也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以下二阴释小利贞。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰：君子所以不得大有为于世，而惟小利于贞者，盖以下之群阴浸长，而小人之党渐盛也。</p></li><li><p>朱氏震曰：二阴浸长，方之于否，不利君子贞，固有闲矣。然不可大贞，利小贞而已。先儒谓居小官干小事，其害未甚，我志犹行。盖遁非疾世避俗，长往不反之谓也。去留迟速，惟时而已。非不忘乎君，不离乎群。消息盈虚，循天而行者，岂能尽遁之时义？</p></li><li><p>张氏清子曰：二阳为临，二阴为遁。遁者，临之反对也。临之《彖》曰：“刚浸而长”，遁之《彖》则不曰“柔浸而长”，而止曰“浸而长”。</p></li></ul><p>遁之时义大矣哉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>阴方浸长，处之为难，故其时义为尤大也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>当阴长之时，不可大贞而尚小利贞者，盖阴长必以浸渐，未能遽盛。君子尚可小贞其道，所谓小利贞，扶持使未遂亡也。遁者，阴之始长。君子知㣲，故当深戒。而圣人之意，未便遽已也，故有与时行小利贞之教。圣贤之于天下，虽知道之将废，岂肯坐视其乱而不救？必区区致力于未极之闲，强此之衰，艰彼之进。其暂安苟得，为之孔孟之所屑为也。王允、谢安之于汉晋是也。若有可变之道，可亨之理，更不假言也。此处遁时之道也，故圣人赞其时义大矣哉。或久或速，其义皆大也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰：遁之小利贞，睽之小事吉。不知者遂以为小而不思也。故孔子明其大，而后知小利贞、小事吉者，有大用存焉。</li></ul><p>初六：遁尾，厉，勿用有攸往</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>遁而在后，尾之象，危之道也。占者不可以有所往，但晦处静俟，可免灾耳。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>它卦以下为初，遁者往遁也。在前者先进，故初乃为尾，尾在后之物也。遁而在后，不及者是也，是以危也。初以柔处㣲（注：此处可能是“内”的误写或特定术语），既已后矣，不可往也，往则危矣。㣲者易于晦藏，往既有危，不若不往之无灾也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏绩曰：阴气已至于二，而初在其后，故曰遁尾也。避难当在前，而在后，故厉。往则与灾难会，故勿用有攸往。</p></li><li><p>孔氏颖达曰：遁尾厉者，为遁之尾，最在后遁者也。小人长于内，应出外以避之，而最在卦内，是遁之为后，故曰遁尾厉也。危厉既至，则当危行言逊，勿用更有所往。</p></li><li><p>朱子语类 问：“遁尾厉，勿用有攸往”者，言不可有所往，但当晦处静俟耳。此意如何？ 曰：程传作不可往，谓不可去也。言遁已后矣，不可往，往则危。往既危，不若不往之无灾。某窃以为不然。遁而在后，尾也，既已危矣，岂可更不往乎？若作占辞看，尤分明。</p></li><li><p>问：“遁尾厉，勿用有攸往”者，言不可有所往，但当晦处静俟耳。此意如何？ 曰：程传作不可往，谓不可去也。言遁已后矣，不可往，往则危。往既危，不若不往之无灾。某窃以为不然。遁而在后，尾也，既已危矣，岂可更不往乎？若作占辞看，尤分明。</p></li><li><p>王氏申子曰：遁往遁也，故遁以初为后。在前者见几先遁，初柔而不能决，止而不能行，故遁而在后，危厉之象也。既已处后，然位居卑下，不往即遁也。若又有所进往，则危厉益甚矣。</p></li><li><p>杨氏启新曰：卦中以二阴为小人，至爻中则均退避之君子。盖皆遁爻，则发遁义也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><ul><li><p>问：易例多取初爻为居先，何独遁而取在后之义？ 曰：因卦义而变者也。初于序则先，然于位则内也。遁者，远出之义也，故以外卦为善。初居最内，岂非在后者乎？</p></li><li><p>问：明夷之初九居内，何以为先几乎？ 曰：明夷则以上卦为内，以上六为主，故也。是以六四入左腹，而六五当内难也。如是，则初又为最远，与遁之义正相反也。</p></li></ul><p>象曰：遁尾之厉，不往何灾也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>见几先遁，固为善也。遁而为尾，危之道也。往既有危，不若不往而晦藏，可免于灾。处危故也。古人处微下隐，乱世而不去者多矣。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>程传以不遁为免灾，朱子以晦处勿有所行为免灾。故朱子尝欲劾韩侂胄，占得此爻而止。</p><p>六二：执之用黄牛之革，莫之胜说</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>以中顺自守，人莫能解，必遁之志也。占者固守亦当如是。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二与五为正应，虽在相违遁之时，二以中正顺应于五，五以中正亲合于二，其交自固。黄中色，牛顺物，革坚固之物。二五以中正顺道相与，其固如执系之以牛革也。莫之胜说，谓其交之固，不可胜言也。在遁之时，故极言之。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>呉氏绮曰：六二居人臣之位，任国家之责，不当遁者也。故六二不言遁。</p></li><li><p>龚氏焕曰：五爻皆言遁，惟六二不言者，二上与五应，虽当遁时，固结而不可遁者也。故有“执用黄牛之革”之象，谓其有必遁之志，似未必然。</p></li><li><p>蔡氏清曰：就隐遁上说，如何见是中顺？盖收敛其德不形于外，不危言激论，不矫矫伸节，惟知自守而已。此之谓中顺。</p></li><li><p>孔氏颖达曰：处中居内，非遁之人也。既非遁之人，便为所遁之主。物皆弃已而遁，何以执固留之？惟有中和厚顺之道，可以固而安之也。能用此道，则无能胜已解脱而去。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此爻传义说亦不同，吴氏、龚氏则畅程传之说，谓六二为五正应，如肺腑之臣，义不可去，箕子所谓“我不顾行遁”是也。蔡氏则申本义之说，谓处遁以中顺之道，如所谓“危行言逊”者，亦与不恶而严之义合。至孔氏则别为一说，谓其能羁縻善类而不使去，执如《雅诗》“执我仇仇”之执。于经文“执之”两字，语气亦自恰合也。故并存其说。</p><p>象曰：执用黄牛，固志也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>上下以中顺之道相固结，其心志甚坚，如执之以牛革也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰：上应贵主，志在辅时，不随物遁，独守中直，坚如革束。执此之志，莫之胜。说殷之父师当此爻矣。</p></li><li><p>蔡氏淸曰：谓自固其志，不可荣以禄也。</p></li></ul><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h3><ul><li>孔氏颖达曰：固志者，坚固遁者之志，使不去己也。</li></ul><p>九三：系遁，有疾厉，畜臣妾吉</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>下比二阴，当遁而有所系之象，有疾而危之道也。然以畜臣妾则吉，盖君子之于小人，惟臣妾则不必其贤而可畜耳，故其占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>阳志说阴，三与二切比，系乎二者也。遁贵速而远，有所系累，则安能速且远也？害于遁矣，故为有疾也。遁而不速，是以危也。臣妾，小人女子，怀恩而不知义，亲爱之则忠其上，系恋之私恩，怀小人女子之道也。故以畜养臣妾则得其心为吉也。然君子之待小人，亦不如是也。三与二非正应，以昵比相亲，非待君子之道。若以正则，虽系不得为有疾。蜀先主之不忍弃士民是也，虽危为无咎矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：九三无应于上，与二相比，处遁之世而意有所系，故曰“系遁”。遁之为义宜远，小人既系于阴，即是有疾惫而致危厉也。亲于所近，系在于下，施之于人，畜养臣妾则可矣，大事则凶，故曰“畜臣妾吉”。</p></li><li><p>胡氏瑗曰：为遁之道在乎远去。九三居内卦之上，切比六二之阴，不能超然远遁，是有疾病而危厉者也。畜臣妾吉者，言九三既不能远遁，然畜群小以臣妾之道，即得其吉。盖臣妾至贱者也可以远则远之，可以近则近之，如此则吉可求也。</p></li><li><p>苏氏浚曰：“畜臣妾吉”示之以待小人之道，见其不可系也。盖小人之易亲如臣妾之易以惑人，畜之法止有不恶而严，严以杜其狎侮之奸，而不恶以柔其忿戾之气。用畜臣妾之法以畜之，庶可以免疾惫而吉耳。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>孔子曰：“惟女子与小人为难养也，近之则不逊，远之则怨。”然则不远不近之间，岂非不恶而严之义乎？故当遁之时，有所系而未得去者，待小人以畜臣妾之道则可矣。胡氏、苏氏说明白。</p><p>象曰：系遁之厉，有疾惫也；畜臣妾吉，不可大事也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>遁而有系累，必以困惫致危。其有疾乃惫也，盖力亦不足矣。以此昵爱之心畜养臣妾则吉，岂可以当大事乎？</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏淸子曰：当遁而系，故有疾而厉，至于惫乏也。惟当以刚自守，止下二阴而畜之以臣妾之道，然后获吉，又岂可当大事乎？</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>不可大事，言未可直行其志，危言危行也，与彖“小贞吉”，大象“不恶而严”之意皆相贯。</p><p>九四：好遁，君子吉，小人否</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>下应初六而干体刚健，有情好而能绝之以遁之象也。惟自克之君子能之，而小人不能，故占者君子则吉而小人否也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四与初为正应，是所好爱者也。君子虽有所好爱，义苟当遁，则去而不疑，所谓克己复礼，以道制欲，是以吉也。小人则不能以义处，昵于所好，牵于所私，至于陷辱其身而不能自拔，故在小人则否也。否，不善也。四干体能刚断，圣人以其处阴而有系，故设小人之戒，恐其失于正也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：有应于阴，不恶而严，故曰“好遁”。小人暗于事几，不忿怒成仇，则私溺为虑矣。</p></li><li><p>朱氏震曰：好者，情之所好也。君子刚决以义断之，舍所好而去，故吉；否者，不能然也。此爻与初六相应，处阴而有所系，故陈小人之戒以佐君子之决。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><ul><li><p>好者，恶之反也。好遁言其不恶也，从容以遁而不为忿戾之行。孟子曰：“予岂若是小丈夫然哉？怒悻悻然见于其面。”正好遁之义也。小人否者，即孟子所谓小丈夫者也。</p></li><li><p>又案：君子吉，小人否。若以小人与君子相敌者言之，则“否”字解如泰否之义。谓好遁者身退道亨，在君子固吉矣，然岂小人之福哉？自古君子退避，则小人亦不旋踵而覆败。是君子之遁者，非君子之凶，乃君子之吉；而致君子之遁者，非小人之泰，乃小人之否也。此义与《剥》上“小人剥庐”之指正同。盖《易》虽不为小人谋，而未尝不为小人戒也。本义以“小利贞”为戒小人之辞，似与此意亦合。</p></li></ul><p>象曰：君子好遁，小人否也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>君子虽有好而能遁，不失于义；小人则不能胜其私意而至于不善也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：爻辞云“好遁君子吉，小人否”。爻传不及“吉”字，盖谓惟君子为能好遁，小人则不能好遁也。既好遁，则遁而亨其吉，不假言矣。</li></ul><p>九五：嘉遁，贞吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>刚阳中正，下应六二亦柔顺而中正，遁之嘉美者也。占者如是而正则吉矣。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>九五中正，遁之嘉美者也。处得中正之道，时止时行，乃所谓嘉美也。故为贞正而吉。九五非无系应，然与二皆以中正自处，是其心志及乎动止，莫非中正而无私系之失，所以为嘉也。在彖则概言遁时，故云“与时行小利贞”，尚有济遁之意。于爻至五，遁将极矣，故惟以中正处遁言之。遁非人君之事故，不主君位言，然人君之所避远，乃遁也，亦在中正而已。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰：“嘉遁贞吉”，即彖传所谓“遁而亨”也。五当位而应，与时偕行者也。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>此爻虽不主君位，然居尊则亦臣之位高者也。凡功成身退者，人臣之道。故伊尹曰：“臣罔以宠利居成功”，岂非遁之嘉美者乎？嘉之义，比好又优矣。</p><p>象曰：嘉遁贞吉，以正志也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>志正则动必由正，所以为遁之嘉也。居中得正而应中正，是其志正也，所以为吉。人之遁也，止也，唯在正其志而已矣。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰：居正处中，能正其志，故获贞吉。</li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>君子之志不在宠利，故进以礼而退以义，所谓正志也。</p><p>上九：肥遁，无不利</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>以刚阳居卦外，下无系应，遁之远而处之裕者也。故其象占如此。肥者，宽裕自得之意。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>肥者，充大宽裕之意。遁者，惟飘然远逝，无所系滞之为善。上九干体刚断，在卦之外矣，又下无所系，是遁之远而无累，可谓宽裕有馀裕也。遁者，穷困之时也，善处则为肥矣。其遁如此，何所不利？</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：最处外极，无应于内，超然绝去，心无疑顾，忧患不能累，矰缴不能及，是以“肥遁无不利”也。</p></li><li><p>姜氏宝曰：四之“好”不如五之“嘉”，五之“嘉”不如上之“肥”。上与二阴无应无系，故肥。肥者，疾惫之反也。</p></li></ul><p>象曰：肥遁无不利，无所疑也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>其遁之远，无所疑滞也。盖在外则已远，无应则无累，故为刚决无疑也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰：最处外极，无应于内，心无疑恋，超世高举，安时无闷，故肥遁无不利。</p></li><li><p>赵氏汝梅曰：四阳之中，三系于阴，四五应于阴，皆不能不自疑。至上则疑虑尽亡，盖无有不利者矣。</p></li><li><p>李氏心传曰：无所疑也。此及升之九三并言之，此决于退，彼决于进，时之宜耳。</p></li></ul><p>总论</p><ul><li>项氏安世曰：下三爻艮也，主于止，故为不往、为执、革、为系遁。上三爻干也，主于行，故为好遁、为嘉遁、为肥遁也。</li></ul>',130)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
